const path = require("path");
const { ethers } = require("ethers");

// Load the EXACT artifact generated by compile.js
const contractArtifact = require(
    path.join(
        __dirname,
        "../build/TransplantChain.json"
    )
);

async function main() {

    console.log("Connecting to Ganache...");

    const provider = new ethers.JsonRpcProvider(
        "http://127.0.0.1:8545"
    );

    // Use a GANACHE DEVELOPMENT ACCOUNT private key
    const privateKey = "0xe5998fd7e36005aa04c58bccbbdd3ef61179a594111820f87e5f9d0a0007e40e";

    const wallet = new ethers.Wallet(
        privateKey,
        provider
    );

    console.log(
        "Deploying from account:",
        wallet.address
    );

    // Check balance
    const balance = await provider.getBalance(
        wallet.address
    );

    console.log(
        "Account balance:",
        ethers.formatEther(balance),
        "ETH"
    );

    // Create contract factory using the SAME artifact
    const factory = new ethers.ContractFactory(
        contractArtifact.abi,
        "0x" + contractArtifact.bytecode,
        wallet
    );

    console.log(
        "Deploying TransplantChain..."
    );

    const contract = await factory.deploy();

    await contract.waitForDeployment();

    const contractAddress =
        await contract.getAddress();

    console.log(
        "🎉 TransplantChain deployed successfully!"
    );

    console.log(
        "📍 Contract Address:",
        contractAddress
    );

    console.log(
        "Transaction Hash:",
        contract.deploymentTransaction().hash
    );
}

main().catch((error) => {

    console.error(
        "❌ Deployment failed:"
    );

    console.error(error);

});